import { readdirSync } from "node:fs";
import { resolve } from "node:path";
import { defineConfig, type Plugin } from "vite";

const root = resolve(import.meta.dirname, "ui");

// Every HTML page in ui/ is an entry: the hand-written pages plus the
// converter pages generated by tools/build-pages.ts.
const pages = Object.fromEntries(
  readdirSync(root)
    .filter((f) => f.endsWith(".html"))
    .map((f) => [f.replace(/\.html$/, ""), resolve(root, f)]),
);

// The pages ship a strict Content-Security-Policy. In development Vite's live
// reload talks over a websocket, so allow it there (and only there).
function allowDevWebsocket(): Plugin {
  return {
    name: "filefusion:dev-csp",
    apply: "serve",
    transformIndexHtml: (html) =>
      html.replace(
        "connect-src 'self'",
        "connect-src 'self' ws://localhost:8000",
      ),
  };
}

export default defineConfig({
  root,
  base: "./",
  plugins: [allowDevWebsocket()],
  server: { port: 8000, strictPort: true },
  preview: { port: 8000, strictPort: true },
  build: {
    outDir: resolve(import.meta.dirname, "dist"),
    emptyOutDir: true,
    target: "es2022",
    rollupOptions: { input: pages },
  },
});
